    'howto.step1Copy': '恐竜の属名を入力して送信してください。系統樹に、推測した属と正解の属がどれほど近縁かが表示されます。',
    'howto.step2': '2. 系統樹を読み解く',
    'howto.step2Copy': '推測するたびに、謎の恐竜と共通する最も細かいクレードが明らかになります。系統樹上で近いほど、正解に近づいています。',
    'howto.step3': '3. ヒント',
