    'howto.intro': 'À chaque défi, un dinosaure mystère est dissimulé. Votre objectif est de trouver son genre grâce aux indices révélés par vos propositions.',
    'howto.step1': '1. Proposez un genre',
    'howto.step1Copy': 'Saisissez le nom d’un dinosaure, puis validez. L’arbre indiquera le degré de parenté entre votre proposition et la cible.',
    'howto.step2': '2. Lisez l’arbre',
    'howto.step2Copy': 'Chaque proposition révèle le clade le plus précis partagé avec le dinosaure mystère. Plus votre proposition est proche dans l’arbre, plus vous vous rapprochez de la réponse.',
    'howto.step3': '3. Indices',
    'howto.step3Copy': 'Vous disposez de 3 indices par défi. Ils révèlent le clade suivant, puis des indices sur le nom du genre lorsque toute la lignée est connue. Vous devez faire 2 propositions entre deux indices.',
    'howto.step4': '4. Cinq niveaux de difficulté',
    'howto.step4Copy': 'Le niveau I propose des genres bien connus. Le niveau V présente des taxons moins connus qui nécessitent de solides connaissances en taxonomie.',
